{
  "claims": [
    {
      "claim_text": "Transaction IDs are only 32 bits wide.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly says transaction IDs have limited size of 32 bits.",
      "citations": [
        {
          "index": 0,
          "quote": "transaction IDs have limited size (32 bits)"
        }
      ]
    },
    {
      "claim_text": "The XID space holds about 4 billion values.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states normal XID comparison is modulo-2^32 and that every normal XID has two billion older and two billion newer XIDs, entailing about 4 billion values.",
      "citations": [
        {
          "index": 1,
          "quote": "Normal XIDs are compared using modulo-232 arithmetic. This means that for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_text": "Every normal XID has roughly two billion older and two billion newer XIDs.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states this directly.",
      "citations": [
        {
          "index": 1,
          "quote": "for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_text": "Every table must be vacuumed at least once every two billion transactions.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states it is necessary to vacuum every table in every database at least once every two billion transactions.",
      "citations": [
        {
          "index": 0,
          "quote": "it is necessary to vacuum every table in every database at least once every two billion transactions"
        }
      ]
    },
    {
      "claim_text": "Running past that without vacuuming can cause data loss.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says that if a table goes unvacuumed longer than the maximum interval, data loss could result.",
      "citations": [
        {
          "index": 2,
          "quote": "If it were to go unvacuumed for longer than that, data loss could result."
        }
      ]
    },
    {
      "claim_text": "That data loss is permanent and unrecoverable.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages call the consequence catastrophic data loss but also say the data is still there; they do not state that the loss is permanent or unrecoverable.",
      "citations": []
    },
    {
      "claim_text": "The default autovacuum_freeze_max_age is 200 million transactions.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states the default is 200 million transactions in the context of autovacuum_freeze_max_age.",
      "citations": [
        {
          "index": 5,
          "quote": "The default, 200 million transactions, translates to about 50MB of pg_xact storage and about 2GB of pg_commit_ts storage."
        }
      ]
    },
    {
      "claim_text": "With the default autovacuum_freeze_max_age of 200 million transactions, the anti-wraparound autovacuum kicks in after about 10% of the two-billion-transaction window.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state autovacuum is invoked when unfrozen rows have XIDs older than autovacuum_freeze_max_age, the default is 200 million, and the normal comparison window is about two billion transactions, making 200 million about 10% of the window.",
      "citations": [
        {
          "index": 2,
          "quote": "autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than the age specified by the configuration parameter autovacuum_freeze_max_age"
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        },
        {
          "index": 1,
          "quote": "for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_text": "The effective maximum for vacuum_freeze_table_age is 95% of autovacuum_freeze_max_age.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states this directly.",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age"
        }
      ]
    },
    {
      "claim_text": "With the default, vacuum_freeze_table_age can be at most 180 million.",
      "verdict": "CONTRADICTED",
      "reasoning": "The default autovacuum_freeze_max_age is 200 million and the effective maximum is 95% of that, which is 190 million, not 180 million.",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age"
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_text": "If autovacuum still fails, warnings start when the oldest XIDs are forty million transactions from wraparound.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states warnings are emitted when the database's oldest XIDs reach forty million transactions from the wraparound point after autovacuum fails to clear old XIDs.",
      "citations": [
        {
          "index": 6,
          "quote": "If for some reason autovacuum fails to clear old XIDs from a table, the system will begin to emit warning messages like this when the database's oldest XIDs reach forty million transactions from the wraparound point"
        }
      ]
    },
    {
      "claim_text": "New XIDs are refused once fewer than three million remain.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound.",
      "citations": [
        {
          "index": 7,
          "quote": "the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_text": "There is a 37-million-transaction window between the first warning and the hard stop.",
      "verdict": "SUPPORTED",
      "reasoning": "Warnings start at forty million transactions from wraparound and XID assignment is refused at fewer than three million remaining, so the interval is 40 million minus 3 million, or 37 million transactions.",
      "citations": [
        {
          "index": 6,
          "quote": "oldest XIDs reach forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_text": "Once XID assignment stops, no new transactions of any kind can be started.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says that in this condition read-only transactions can still be started, so it is false that no new transactions of any kind can start.",
      "citations": [
        {
          "index": 8,
          "quote": "In this condition any transactions already in progress can continue, but only read-only transactions can be started."
        }
      ]
    }
  ]
}
